INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-05-D15', 'n_somat_coliphagen = count_rows(validierungsproben, organismus == ''somatische_coliphagen'')', ARRAY['validierungsproben']::text[], 'n_somat_coliphagen', NULL, '§3.3.3', 'Plan 3: Anzahl vollständiger Probenpaare — somatische Coliphagen — "sind je 16 korrespondierende Proben im Zulauf und Ablauf zu nehmen" (L679); Zeilen mit organismus = ''somatische_coliphagen''.', 'imported_unverified', 'Beim vereinfachten Validierungsmonitoring werden die zu validierenden $\log _{10}$-Reduktionen für den gesamten Aufbereitungszug auf Basis eines paarweisen Vergleichs von Zu- und Ablaufproben (sogenannter Binomialansatz) nachgewiesen. Dabei werden $\log _{10}$-Reduktionen jeweils paarweise aus korrespondierenden Zu- und Ablaufproben berechnet. Abweichend von der Mindestanzahl gemäß EU-WasserWVVO (mindestens drei Proben pro Stichprobenpunkt) und in Anlehnung an die EU-Badegewässerrichtlinie 2006/7/EG sind je 16 korrespondierende Proben im Zulauf und Ablauf zu nehmen. Die Beurteilung erfolgt wie folgt:'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-05-D16', 'n_erreicht_somat_coliphagen = count_rows(validierungsproben, organismus == ''somatische_coliphagen'' AND erreicht == 1)', ARRAY['validierungsproben']::text[], 'n_erreicht_somat_coliphagen', NULL, '§3.3.3', 'Plan 3: Probenpaare mit erreichtem Leistungsziel — somatische Coliphagen — Leistungsziel erreicht oder überschritten, oder Ablauf < 1 KBE bzw. PFU je 100 ml (L681 / L683); Zeilen mit organismus = ''somatische_coliphagen''.', 'imported_unverified', 'I Wassergüte-Klasse A: In mindestens 15 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel einmal nicht erreicht wird, darf dieses um nicht mehr als $1,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt. — I Wassergüte-Klassen B-1 und C-1: In mindestens 8 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel nicht erreicht wird, darf dieses um nicht mehr als $2,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-05-D17', 'max_unterschreitung_somat_coliphagen = max_rows(validierungsproben, shortfall, organismus == ''somatische_coliphagen'')', ARRAY['validierungsproben']::text[], 'max_unterschreitung_somat_coliphagen', 'log10', '§3.3.3', 'Plan 3: Größte Unterschreitung des Leistungsziels — somatische Coliphagen — zulässig ≤ 1,0 log10 (A) / ≤ 2,0 log10 (B-1, C-1) (L681 / L683); Zeilen mit organismus = ''somatische_coliphagen''; ohne Zeile des Organismus unentscheidbar.', 'imported_unverified', 'I Wassergüte-Klasse A: In mindestens 15 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel einmal nicht erreicht wird, darf dieses um nicht mehr als $1,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt. — I Wassergüte-Klassen B-1 und C-1: In mindestens 8 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel nicht erreicht wird, darf dieses um nicht mehr als $2,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-05-D18', 'mw_somat_coliphagen_calc = mean_rows(validierungsproben, lrv_i, organismus == ''somatische_coliphagen'')', ARRAY['validierungsproben']::text[], 'mw_somat_coliphagen_calc', 'log10', 'Anhang C.2', 'Plan 3: Mittelwert MW der log10-Reduktionen — somatische Coliphagen — mean_rows über die Zeilen des Organismus (L1821); Zeilen mit organismus = ''somatische_coliphagen''; ohne Zeile des Organismus unentscheidbar; Zwilling der typbaren mw_log10 / sd_log10 (m1200_2-D-4).', 'imported_unverified', 'Aus der Gesamtheit der ermittelten $\log _{10}$-Reduktionswerte kann das geforderte Perzentil analytisch berechnet werden, wobei der Median, der Mittelwert (MW) und die Standardabweichung der Stichprobe (SD) verwendet werden. Die Ermittlung ist beispielhaft in Bild C. 1 dargestellt.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
