INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-05-D20', 'p10_somat_coliphagen_calc = mean_rows(validierungsproben, lrv_i, organismus == ''somatische_coliphagen'') - lookup(''GL_C2_1'', ''k'', ''wert'') * stdev_rows(validierungsproben, lrv_i, organismus == ''somatische_coliphagen'')', ARRAY['validierungsproben']::text[], 'p10_somat_coliphagen_calc', 'log10', 'Anhang C.2, Gl. C.2-1', 'Plan 3: 10. Perzentil = MW − 1,282 · SD — somatische Coliphagen — k aus GL_C2_1 (L1822); Zeilen mit organismus = ''somatische_coliphagen''; Stichproben-Standardabweichung (n − 1), mindestens 2 Zeilen; ohne Zeile des Organismus unentscheidbar; Zwilling der prod-Gleichung Gl. C.2-1 / C.2-2 über die Skalare (m1200_2-D-4).', 'imported_unverified', '10. Perzentil $=\mathrm{MW}-1,282 \cdot \mathrm{SD}$ (als Schätzwert der Wahrscheinlichkeitsverteilung; Klasse A)'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2'
