SELECT w.id, 'M12002-05-D21', 'p50_somat_coliphagen_calc = median_rows(validierungsproben, lrv_i, organismus == ''somatische_coliphagen'')', ARRAY['validierungsproben']::text[], 'p50_somat_coliphagen_calc', 'log10', 'Anhang C.2, Gl. C.2-2', 'Plan 3: 50. Perzentil (Median) — somatische Coliphagen — median_rows über die Zeilen des Organismus (L1823); Zeilen mit organismus = ''somatische_coliphagen''; ohne Zeile des Organismus unentscheidbar; Zwilling der prod-Gleichung Gl. C.2-1 / C.2-2 über die Skalare (m1200_2-D-4).', 'imported_unverified', '50. Perzentil = Median (Klassen B-1 und C-1)'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2'
