INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-05-D22', 'validierung_ok_somat_coliphagen = if(count_rows(validierungsproben, organismus == ''somatische_coliphagen'') >= lookup(''S3_3_3'', wassergueteklasse, ''n_total'') AND count_rows(validierungsproben, organismus == ''somatische_coliphagen'' AND erreicht == 1) >= lookup(''S3_3_3'', wassergueteklasse, ''n_pass_min'') AND max_rows(validierungsproben, shortfall, organismus == ''somatische_coliphagen'') <= lookup(''S3_3_3'', wassergueteklasse, ''max_shortfall_log10''), 1, 0)', ARRAY['validierungsproben','wassergueteklasse']::text[], 'validierung_ok_somat_coliphagen', NULL, '§3.3.3', 'Plan 3: Vereinfachtes Validierungsmonitoring bestanden (1 = ja) — somatische Coliphagen — ≥ 16 Paare, ≥ 15 (A) / ≥ 8 (B-1, C-1) erreicht, größte Unterschreitung ≤ 1,0 / 2,0 log10 (S3_3_3; L681 / L683); ohne S3_3_3-Zeile (B-2, C-2, D) unentscheidbar; Zeilen mit organismus = ''somatische_coliphagen''; REQ-04 / REQ-05 STAGED (m1200_2-G-7 / -G-1).', 'imported_unverified', 'Beim vereinfachten Validierungsmonitoring werden die zu validierenden $\log _{10}$-Reduktionen für den gesamten Aufbereitungszug auf Basis eines paarweisen Vergleichs von Zu- und Ablaufproben (sogenannter Binomialansatz) nachgewiesen. Dabei werden $\log _{10}$-Reduktionen jeweils paarweise aus korrespondierenden Zu- und Ablaufproben berechnet. Abweichend von der Mindestanzahl gemäß EU-WasserWVVO (mindestens drei Proben pro Stichprobenpunkt) und in Anlehnung an die EU-Badegewässerrichtlinie 2006/7/EG sind je 16 korrespondierende Proben im Zulauf und Ablauf zu nehmen. Die Beurteilung erfolgt wie folgt: — I Wassergüte-Klasse A: In mindestens 15 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel einmal nicht erreicht wird, darf dieses um nicht mehr als $1,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt. — I Wassergüte-Klassen B-1 und C-1: In mindestens 8 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel nicht erreicht wird, darf dieses um nicht mehr als $2,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-05-D23', 'perzentil_ok_somat_coliphagen = if(if(lookup(''ANHANGC1'', wassergueteklasse, ''percentile'') == 10, mean_rows(validierungsproben, lrv_i, organismus == ''somatische_coliphagen'') - lookup(''GL_C2_1'', ''k'', ''wert'') * stdev_rows(validierungsproben, lrv_i, organismus == ''somatische_coliphagen''), median_rows(validierungsproben, lrv_i, organismus == ''somatische_coliphagen'')) >= lookup(''TAB3'', wassergueteklasse, ''log10_somatische_coliphagen''), 1, 0)', ARRAY['validierungsproben','wassergueteklasse']::text[], 'perzentil_ok_somat_coliphagen', NULL, 'Anhang C.1 / C.2', 'Plan 3: Umfängliches Validierungsmonitoring: gefordertes Perzentil ≥ Leistungsziel (1 = ja) — somatische Coliphagen — 10. Perzentil (A) bzw. Median (B-1, C-1) nach ANHANGC1 gegen das TAB3-Ziel (L1800 / L1802); Zeilen mit organismus = ''somatische_coliphagen''; Stichproben-Standardabweichung (n − 1), mindestens 2 Zeilen; REQ-06 STAGED (m1200_2-G-2).', 'imported_unverified', 'I Klasse A: Das 10. Perzentil der Verteilung der $\log _{10}$-Reduktionen muss das Leistungsziel erreichen oder übersteigen. — I Klassen B-1 und C-1: Das 50. Perzentil (Median) der Verteilung der $\log _{10}$-Reduktionen muss das Leistungsziel erreichen oder übersteigen. — 10. Perzentil $=\mathrm{MW}-1,282 \cdot \mathrm{SD}$ (als Schätzwert der Wahrscheinlichkeitsverteilung; Klasse A) — 50. Perzentil = Median (Klassen B-1 und C-1)'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
