SELECT w.id, 'M12002-05-D30', 'p50_fspez_coliphagen_calc = median_rows(validierungsproben, lrv_i, organismus == ''f_spez_coliphagen'')', ARRAY['validierungsproben']::text[], 'p50_fspez_coliphagen_calc', 'log10', 'Anhang C.2, Gl. C.2-2', 'Plan 3: 50. Perzentil (Median) — f-spezifische Coliphagen — median_rows über die Zeilen des Organismus (L1823); Zeilen mit organismus = ''f_spez_coliphagen''; ohne Zeile des Organismus unentscheidbar; Zwilling der prod-Gleichung Gl. C.2-1 / C.2-2 über die Skalare (m1200_2-D-4).', 'imported_unverified', '50. Perzentil = Median (Klassen B-1 und C-1)'
