ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-05-D44', 'max_unterschreitung_sulfatreduzierer = max_rows(validierungsproben, shortfall, organismus == ''sulfatreduzierer'')', ARRAY['validierungsproben']::text[], 'max_unterschreitung_sulfatreduzierer', 'log10', '§3.3.3', 'Plan 3: Größte Unterschreitung des Leistungsziels — sulfatreduzierende Sporenbildner — zulässig ≤ 1,0 log10 (A) / ≤ 2,0 log10 (B-1, C-1) (L681 / L683); Zeilen mit organismus = ''sulfatreduzierer''; ohne Zeile des Organismus unentscheidbar.', 'imported_unverified', 'I Wassergüte-Klasse A: In mindestens 15 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel einmal nicht erreicht wird, darf dieses um nicht mehr als $1,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt. — I Wassergüte-Klassen B-1 und C-1: In mindestens 8 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel nicht erreicht wird, darf dieses um nicht mehr als $2,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-05-D45', 'mw_sulfatreduzierer_calc = mean_rows(validierungsproben, lrv_i, organismus == ''sulfatreduzierer'')', ARRAY['validierungsproben']::text[], 'mw_sulfatreduzierer_calc', 'log10', 'Anhang C.2', 'Plan 3: Mittelwert MW der log10-Reduktionen — sulfatreduzierende Sporenbildner — mean_rows über die Zeilen des Organismus (L1821); Zeilen mit organismus = ''sulfatreduzierer''; ohne Zeile des Organismus unentscheidbar; Zwilling der typbaren mw_log10 / sd_log10 (m1200_2-D-4).', 'imported_unverified', 'Aus der Gesamtheit der ermittelten $\log _{10}$-Reduktionswerte kann das geforderte Perzentil analytisch berechnet werden, wobei der Median, der Mittelwert (MW) und die Standardabweichung der Stichprobe (SD) verwendet werden. Die Ermittlung ist beispielhaft in Bild C. 1 dargestellt.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-05-D46', 'sd_sulfatreduzierer_calc = stdev_rows(validierungsproben, lrv_i, organismus == ''sulfatreduzierer'')', ARRAY['validierungsproben']::text[], 'sd_sulfatreduzierer_calc', 'log10', 'Anhang C.2', 'Plan 3: Standardabweichung SD der Stichprobe — sulfatreduzierende Sporenbildner — stdev_rows (Stichprobe, n − 1) über die Zeilen des Organismus (L1821); mindestens 2 Zeilen; Zeilen mit organismus = ''sulfatreduzierer''; Stichproben-Standardabweichung (n − 1), mindestens 2 Zeilen; ohne Zeile des Organismus unentscheidbar; Zwilling der typbaren mw_log10 / sd_log10 (m1200_2-D-4).', 'imported_unverified', 'Aus der Gesamtheit der ermittelten $\log _{10}$-Reduktionswerte kann das geforderte Perzentil analytisch berechnet werden, wobei der Median, der Mittelwert (MW) und die Standardabweichung der Stichprobe (SD) verwendet werden. Die Ermittlung ist beispielhaft in Bild C. 1 dargestellt.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-05-D47', 'p10_sulfatreduzierer_calc = mean_rows(validierungsproben, lrv_i, organismus == ''sulfatreduzierer'') - lookup(''GL_C2_1'', ''k'', ''wert'') * stdev_rows(validierungsproben, lrv_i, organismus == ''sulfatreduzierer'')', ARRAY['validierungsproben']::text[], 'p10_sulfatreduzierer_calc', 'log10', 'Anhang C.2, Gl. C.2-1', 'Plan 3: 10. Perzentil = MW − 1,282 · SD — sulfatreduzierende Sporenbildner — k aus GL_C2_1 (L1822); Zeilen mit organismus = ''sulfatreduzierer''; Stichproben-Standardabweichung (n − 1), mindestens 2 Zeilen; ohne Zeile des Organismus unentscheidbar; Zwilling der prod-Gleichung Gl. C.2-1 / C.2-2 über die Skalare (m1200_2-D-4).', 'imported_unverified', '10. Perzentil $=\mathrm{MW}-1,282 \cdot \mathrm{SD}$ (als Schätzwert der Wahrscheinlichkeitsverteilung; Klasse A)'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-05-D48', 'p50_sulfatreduzierer_calc = median_rows(validierungsproben, lrv_i, organismus == ''sulfatreduzierer'')', ARRAY['validierungsproben']::text[], 'p50_sulfatreduzierer_calc', 'log10', 'Anhang C.2, Gl. C.2-2', 'Plan 3: 50. Perzentil (Median) — sulfatreduzierende Sporenbildner — median_rows über die Zeilen des Organismus (L1823); Zeilen mit organismus = ''sulfatreduzierer''; ohne Zeile des Organismus unentscheidbar; Zwilling der prod-Gleichung Gl. C.2-1 / C.2-2 über die Skalare (m1200_2-D-4).', 'imported_unverified', '50. Perzentil = Median (Klassen B-1 und C-1)'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-05-D49', 'validierung_ok_sulfatreduzierer = if(count_rows(validierungsproben, organismus == ''sulfatreduzierer'') >= lookup(''S3_3_3'', wassergueteklasse, ''n_total'') AND count_rows(validierungsproben, organismus == ''sulfatreduzierer'' AND erreicht == 1) >= lookup(''S3_3_3'', wassergueteklasse, ''n_pass_min'') AND max_rows(validierungsproben, shortfall, organismus == ''sulfatreduzierer'') <= lookup(''S3_3_3'', wassergueteklasse, ''max_shortfall_log10''), 1, 0)', ARRAY['validierungsproben','wassergueteklasse']::text[], 'validierung_ok_sulfatreduzierer', NULL, '§3.3.3', 'Plan 3: Vereinfachtes Validierungsmonitoring bestanden (1 = ja) — sulfatreduzierende Sporenbildner — ≥ 16 Paare, ≥ 15 (A) / ≥ 8 (B-1, C-1) erreicht, größte Unterschreitung ≤ 1,0 / 2,0 log10 (S3_3_3; L681 / L683); ohne S3_3_3-Zeile (B-2, C-2, D) unentscheidbar; Zeilen mit organismus = ''sulfatreduzierer''; REQ-04 / REQ-05 STAGED (m1200_2-G-7 / -G-1).', 'imported_unverified', 'Beim vereinfachten Validierungsmonitoring werden die zu validierenden $\log _{10}$-Reduktionen für den gesamten Aufbereitungszug auf Basis eines paarweisen Vergleichs von Zu- und Ablaufproben (sogenannter Binomialansatz) nachgewiesen. Dabei werden $\log _{10}$-Reduktionen jeweils paarweise aus korrespondierenden Zu- und Ablaufproben berechnet. Abweichend von der Mindestanzahl gemäß EU-WasserWVVO (mindestens drei Proben pro Stichprobenpunkt) und in Anlehnung an die EU-Badegewässerrichtlinie 2006/7/EG sind je 16 korrespondierende Proben im Zulauf und Ablauf zu nehmen. Die Beurteilung erfolgt wie folgt: — I Wassergüte-Klasse A: In mindestens 15 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel einmal nicht erreicht wird, darf dieses um nicht mehr als $1,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt. — I Wassergüte-Klassen B-1 und C-1: In mindestens 8 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel nicht erreicht wird, darf dieses um nicht mehr als $2,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-05-D50', 'perzentil_ok_sulfatreduzierer = if(if(lookup(''ANHANGC1'', wassergueteklasse, ''percentile'') == 10, mean_rows(validierungsproben, lrv_i, organismus == ''sulfatreduzierer'') - lookup(''GL_C2_1'', ''k'', ''wert'') * stdev_rows(validierungsproben, lrv_i, organismus == ''sulfatreduzierer''), median_rows(validierungsproben, lrv_i, organismus == ''sulfatreduzierer'')) >= lookup(''TAB3'', wassergueteklasse, ''log10_sulfatreduzierer''), 1, 0)', ARRAY['validierungsproben','wassergueteklasse']::text[], 'perzentil_ok_sulfatreduzierer', NULL, 'Anhang C.1 / C.2', 'Plan 3: Umfängliches Validierungsmonitoring: gefordertes Perzentil ≥ Leistungsziel (1 = ja) — sulfatreduzierende Sporenbildner — 10. Perzentil (A) bzw. Median (B-1, C-1) nach ANHANGC1 gegen das TAB3-Ziel (L1800 / L1802); Zeilen mit organismus = ''sulfatreduzierer''; Stichproben-Standardabweichung (n − 1), mindestens 2 Zeilen; REQ-06 STAGED (m1200_2-G-2).', 'imported_unverified', 'I Klasse A: Das 10. Perzentil der Verteilung der $\log _{10}$-Reduktionen muss das Leistungsziel erreichen oder übersteigen. — I Klassen B-1 und C-1: Das 50. Perzentil (Median) der Verteilung der $\log _{10}$-Reduktionen muss das Leistungsziel erreichen oder übersteigen. — 10. Perzentil $=\mathrm{MW}-1,282 \cdot \mathrm{SD}$ (als Schätzwert der Wahrscheinlichkeitsverteilung; Klasse A) — 50. Perzentil = Median (Klassen B-1 und C-1)'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-05' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-06-D1', 'konformitaet_calc = count_rows(routineproben_1200_2, ok == 1) * 100 / count_rows(routineproben_1200_2, relevant == 1)', ARRAY['routineproben_1200_2']::text[], 'konformitaet_calc', '%', '§3.1; §6.4', 'Plan 3: Anteil der Routineproben, die den Tab.-3-Wert ihrer Klasse einhalten (Legionella strikt "<", sonst "≤"; Proben ohne gedruckten Wert zählen weder im Zähler noch im Nenner; 100 = Prozent; keine Probe mit Wert ⇒ unentscheidbar, nie 0); "in mindestens 90 % der Proben eingehalten" (L534 / L1283); bis zur Konsumenten-Ergänzung m1200_2-C-1 (wassergueteklasse → -06) sind alle Zeilen "kein Wert"; REQ-03 / perzentil_konformitaet STAGED (m1200_2-G-5 / -D-6); die Abweichungsgrenze (1 log10 / 100 %) ist nicht kodiert (Residuum).', 'imported_unverified', 'Die vorgegebenen Werte für E. coli, Legionella spp. und intestinale Nematoden in Tabelle 3 müssen in mindestens $90 \%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von einer $\log _{10}$-Stufe für den vorgegebenen Wert für $E$. coli und Legionella spp. und $100 \%$ des vorgegebenen Werts für intestinale Nematoden überschreiten. — Für die Qualitätsüberwachung ist angelehnt an die EU-WasserWVVO, Anhang 1, Abschnitt 2, weiterhin gefordert, dass $90 \%$ der Proben die Mindestanforderungen gemäß Tabelle 3 einhalten müssen und die weiteren Proben eine maximale Überschreitung von $1 \log _{10}$-Stufe für E. coli und Legionellen bzw. $100 \%$ für andere Parameter aufweisen dürfen. Dies gilt vorbehaltlich gegebenenfalls weiterergehender Anforderungen, die aus dem Risikomanagementplan resultieren.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-06' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-12-D1', 'credit_sum_viren = sum_rows(verfahrenskette_stufen, credit_viren)', ARRAY['verfahrenskette_stufen']::text[], 'credit_sum_viren', 'log10', '§3.3.2; Anhang B, Tab. B.2', 'Plan 3: Σ erreichbare log10-Reduktion (viren) über die Stufen der Verfahrenskette ("werden … jeweils zu einer Gesamtreduktion addiert (Mehrfachbehandlung, Multibarrierenansatz)", L640); indikative Tab.-B.2-Werte bzw. die je Zeile begründet abweichenden Werte; kein Nachweis (L1913).', 'imported_unverified', 'Für die drei in Tabelle 3 genannten Organismengruppen werden die aus den vorgenannten methodischen Ansätzen ermittelten $\log _{10}$-Reduktionen für einzelne Aufbereitungsstufen jeweils zu einer Gesamtreduktion addiert (Mehrfachbehandlung, Multibarrierenansatz), siehe Beispiel in Bild 1. — Tabelle B.2: Indikative $\log _{10}$-Reduktionen, denen Aufbereitungsstufen zuzuordnen sind (Australian Guidelines for Water Recycling, Draft of Chapters 1, 2, 3 and 5 and Appendices 2 and 3, 2020), mit Ergänzungen zur Einordnung'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-12' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-12-D2', 'credit_sum_protozoen = sum_rows(verfahrenskette_stufen, credit_protozoen)', ARRAY['verfahrenskette_stufen']::text[], 'credit_sum_protozoen', 'log10', '§3.3.2; Anhang B, Tab. B.2', 'Plan 3: Σ erreichbare log10-Reduktion (protozoen) über die Stufen der Verfahrenskette ("werden … jeweils zu einer Gesamtreduktion addiert (Mehrfachbehandlung, Multibarrierenansatz)", L640); indikative Tab.-B.2-Werte bzw. die je Zeile begründet abweichenden Werte; kein Nachweis (L1913).', 'imported_unverified', 'Für die drei in Tabelle 3 genannten Organismengruppen werden die aus den vorgenannten methodischen Ansätzen ermittelten $\log _{10}$-Reduktionen für einzelne Aufbereitungsstufen jeweils zu einer Gesamtreduktion addiert (Mehrfachbehandlung, Multibarrierenansatz), siehe Beispiel in Bild 1. — Tabelle B.2: Indikative $\log _{10}$-Reduktionen, denen Aufbereitungsstufen zuzuordnen sind (Australian Guidelines for Water Recycling, Draft of Chapters 1, 2, 3 and 5 and Appendices 2 and 3, 2020), mit Ergänzungen zur Einordnung'
