INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-12-D3', 'credit_sum_bakterien = sum_rows(verfahrenskette_stufen, credit_bakterien)', ARRAY['verfahrenskette_stufen']::text[], 'credit_sum_bakterien', 'log10', '§3.3.2; Anhang B, Tab. B.2', 'Plan 3: Σ erreichbare log10-Reduktion (bakterien) über die Stufen der Verfahrenskette ("werden … jeweils zu einer Gesamtreduktion addiert (Mehrfachbehandlung, Multibarrierenansatz)", L640); indikative Tab.-B.2-Werte bzw. die je Zeile begründet abweichenden Werte; kein Nachweis (L1913).', 'imported_unverified', 'Für die drei in Tabelle 3 genannten Organismengruppen werden die aus den vorgenannten methodischen Ansätzen ermittelten $\log _{10}$-Reduktionen für einzelne Aufbereitungsstufen jeweils zu einer Gesamtreduktion addiert (Mehrfachbehandlung, Multibarrierenansatz), siehe Beispiel in Bild 1. — Tabelle B.2: Indikative $\log _{10}$-Reduktionen, denen Aufbereitungsstufen zuzuordnen sind (Australian Guidelines for Water Recycling, Draft of Chapters 1, 2, 3 and 5 and Appendices 2 and 3, 2020), mit Ergänzungen zur Einordnung'
