INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-12-D4', 'credit_ok_viren = if(sum_rows(verfahrenskette_stufen, credit_viren) >= lookup(''TAB3'', wassergueteklasse, ''log10_somatische_coliphagen''), 1, 0)', ARRAY['verfahrenskette_stufen','wassergueteklasse']::text[], 'credit_ok_viren', NULL, '§3.3.2; §3.1, Tab. 3', 'Plan 3: 1 wenn die Σ der indikativen Credits (viren) das Tab.-3-Leistungsziel der geerbten Klasse erreicht — Coliphagen ≥ 6,0 (somatische und f-spezifische drucken denselben Wert); Planungs-Hinweis (Bild 1), kein Gate: die Validierung nach §3.3.3 / Anhang C bleibt der Nachweis.', 'imported_unverified', 'Für die drei in Tabelle 3 genannten Organismengruppen werden die aus den vorgenannten methodischen Ansätzen ermittelten $\log _{10}$-Reduktionen für einzelne Aufbereitungsstufen jeweils zu einer Gesamtreduktion addiert (Mehrfachbehandlung, Multibarrierenansatz), siehe Beispiel in Bild 1. — \hline く & Mechanisch－ biologische Behandlung， Filtration， Desinfektion & $\leq 10^{\mathrm{a})}$ & $\leq 100$ & \multirow{5}{*}{\begin{tabular}{l}
Legionella spp．： $<1.000 \mathrm{KBE} / \mathrm{L}$ ， wenn das Risiko der Aerosolbil－ dung besteht； \\
intestinale Nematoden （Eier von Hel－ minthen）：$\leq 1$ Ei pro Liter für die Bewässerung von Weide－ flächen oder Futterpflanzen
\end{tabular}} & $\mathrm{BSB}_{5} \leq 10 \mathrm{mg} / \mathrm{l}^{\text {d）}}$ AFS $\leq 10 \mathrm{mg} / \mathrm{l}^{\mathrm{g})}$ Trübung $\leq 2 \mathrm{NTU}{ }^{\mathrm{fl}}$ & E．coli $\geqslant 5,0$ Somatische Coliphagen， insg．$\geq 6,0^{\text {g）}}$ f－spezifsche Coliphagen， insg．$\geq 6,0^{\text {g）}}$ Clostridium－perfrin－ gens－Sporen $\geqslant 4,0 \mathrm{bzw}$ ．sulfatre－ duzierende Sporen－ bildner $\geqslant 5,0$ \\'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-12' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-12-D5', 'credit_ok_protozoen = if(sum_rows(verfahrenskette_stufen, credit_protozoen) >= lookup(''TAB3'', wassergueteklasse, ''log10_clostridium''), 1, 0)', ARRAY['verfahrenskette_stufen','wassergueteklasse']::text[], 'credit_ok_protozoen', NULL, '§3.3.2; §3.1, Tab. 3', 'Plan 3: 1 wenn die Σ der indikativen Credits (protozoen) das Tab.-3-Leistungsziel der geerbten Klasse erreicht — Clostridium-perfringens-Sporen ≥ 4,0 (das alternativ gedruckte Ziel sulfatreduzierende Sporenbildner ≥ 5,0 ist strenger — m1200_2-J-3); Planungs-Hinweis (Bild 1), kein Gate: die Validierung nach §3.3.3 / Anhang C bleibt der Nachweis.', 'imported_unverified', 'Für die drei in Tabelle 3 genannten Organismengruppen werden die aus den vorgenannten methodischen Ansätzen ermittelten $\log _{10}$-Reduktionen für einzelne Aufbereitungsstufen jeweils zu einer Gesamtreduktion addiert (Mehrfachbehandlung, Multibarrierenansatz), siehe Beispiel in Bild 1. — \hline く & Mechanisch－ biologische Behandlung， Filtration， Desinfektion & $\leq 10^{\mathrm{a})}$ & $\leq 100$ & \multirow{5}{*}{\begin{tabular}{l}
Legionella spp．： $<1.000 \mathrm{KBE} / \mathrm{L}$ ， wenn das Risiko der Aerosolbil－ dung besteht； \\
intestinale Nematoden （Eier von Hel－ minthen）：$\leq 1$ Ei pro Liter für die Bewässerung von Weide－ flächen oder Futterpflanzen
\end{tabular}} & $\mathrm{BSB}_{5} \leq 10 \mathrm{mg} / \mathrm{l}^{\text {d）}}$ AFS $\leq 10 \mathrm{mg} / \mathrm{l}^{\mathrm{g})}$ Trübung $\leq 2 \mathrm{NTU}{ }^{\mathrm{fl}}$ & E．coli $\geqslant 5,0$ Somatische Coliphagen， insg．$\geq 6,0^{\text {g）}}$ f－spezifsche Coliphagen， insg．$\geq 6,0^{\text {g）}}$ Clostridium－perfrin－ gens－Sporen $\geqslant 4,0 \mathrm{bzw}$ ．sulfatre－ duzierende Sporen－ bildner $\geqslant 5,0$ \\'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-12' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-12-D6', 'credit_ok_bakterien = if(sum_rows(verfahrenskette_stufen, credit_bakterien) >= lookup(''TAB3'', wassergueteklasse, ''log10_e_coli''), 1, 0)', ARRAY['verfahrenskette_stufen','wassergueteklasse']::text[], 'credit_ok_bakterien', NULL, '§3.3.2; §3.1, Tab. 3', 'Plan 3: 1 wenn die Σ der indikativen Credits (bakterien) das Tab.-3-Leistungsziel der geerbten Klasse erreicht — E. coli ≥ 5,0; Planungs-Hinweis (Bild 1), kein Gate: die Validierung nach §3.3.3 / Anhang C bleibt der Nachweis.', 'imported_unverified', 'Für die drei in Tabelle 3 genannten Organismengruppen werden die aus den vorgenannten methodischen Ansätzen ermittelten $\log _{10}$-Reduktionen für einzelne Aufbereitungsstufen jeweils zu einer Gesamtreduktion addiert (Mehrfachbehandlung, Multibarrierenansatz), siehe Beispiel in Bild 1. — \hline く & Mechanisch－ biologische Behandlung， Filtration， Desinfektion & $\leq 10^{\mathrm{a})}$ & $\leq 100$ & \multirow{5}{*}{\begin{tabular}{l}
Legionella spp．： $<1.000 \mathrm{KBE} / \mathrm{L}$ ， wenn das Risiko der Aerosolbil－ dung besteht； \\
intestinale Nematoden （Eier von Hel－ minthen）：$\leq 1$ Ei pro Liter für die Bewässerung von Weide－ flächen oder Futterpflanzen
\end{tabular}} & $\mathrm{BSB}_{5} \leq 10 \mathrm{mg} / \mathrm{l}^{\text {d）}}$ AFS $\leq 10 \mathrm{mg} / \mathrm{l}^{\mathrm{g})}$ Trübung $\leq 2 \mathrm{NTU}{ }^{\mathrm{fl}}$ & E．coli $\geqslant 5,0$ Somatische Coliphagen， insg．$\geq 6,0^{\text {g）}}$ f－spezifsche Coliphagen， insg．$\geq 6,0^{\text {g）}}$ Clostridium－perfrin－ gens－Sporen $\geqslant 4,0 \mathrm{bzw}$ ．sulfatre－ duzierende Sporen－ bildner $\geqslant 5,0$ \\'
