INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-13-D1', 'parameter_count = count_rows(betriebsparameter)', ARRAY['betriebsparameter']::text[], 'parameter_count', NULL, '§6.4, Tab. 6', 'Plan 3: Anzahl vollständiger Betriebsparameter-Zeilen ("Es sind mindestens die Betriebsparameter gemäß Tabelle 6 zu berücksichtigen", L663).', 'imported_unverified', 'Mit beiden Varianten werden die Mindestanforderungen an die Betriebsbedingungen für die Aufbereitungseinrichtung, insbesondere die relevanten Betriebsparameter und deren Anwendungsbereiche (Betriebsfenster) spezifiziert. Es sind mindestens die Betriebsparameter gemäß Tabelle 6 zu berücksichtigen. Hinweise zu relevanten Einflussfaktoren und relevanten Betriebsparametern können auch Tabelle 5 entnommen werden. Die spezifizierten Mindestanforderungen an die Betriebsparameter sind während der Inbetriebnahmephase und im Regelbetrieb einzuhalten.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-13' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-13-D2', 'parameter_nicht_online = count_rows(betriebsparameter, online_ok == 0)', ARRAY['betriebsparameter']::text[], 'parameter_nicht_online', NULL, '§6.4', 'Plan 3: Betriebsparameter ohne Online-Messung ("Durch Online-Monitoring von relevanten Betriebsparametern sind der Betriebszustand und die Einhaltung der Anforderungen zu allen Zeitpunkten sicherzustellen", L1287); REQ-11 (messhauefigkeit == online) STAGED (m1200_2-G-6).', 'imported_unverified', 'Die Messhäufigkeit von Betriebsparametern muss die Systemträgheit berücksichtigen. Die Systemträgheit, evaluiert als hydraulische Verweilzeit, bestimmt die Dynamik für Gegenmaßnahmen, sodass kein Wasser der Wiederverwendung zugeführt wird, das die Anforderungen nicht erfüllt. Die regelmäßige Überprüfung der Betriebsparameter dient der Einhaltung der zulässigen Betriebsbedingungen und gewährleistet damit der Einhaltung der Qualitätsanforderungen und Leistungsziele.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-13' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-13-D3', 'alarm_verzoegerung_max_calc = max_rows(betriebsparameter, alarm_verzoegerung_min, alarm_verzoegerung_min IS NOT NULL)', ARRAY['betriebsparameter']::text[], 'alarm_verzoegerung_max_calc', 'min', '§6.4', 'Plan 3: größte eingetragene Alarmverzögerung über die Zeilen ("Abweichungen vom zulässigen Betriebsfenster sollten je nach System nach 5 min bis 30 min eine Alarmierung auslösen", L1289 — SR-2: der Bereich wird angezeigt, geprüft wird das prod-Gate-Maximum 30 min); Zeilen ohne Eintrag zählen nicht; Übernahme als alarm_verzoegerung_min / REQ-11 STAGED (m1200_2-D-8 / -G-6).', 'imported_unverified', 'Durch Online-Monitoring von relevanten Betriebsparametern sind der Betriebszustand und die Einhaltung der Anforderungen zu allen Zeitpunkten sicherzustellen und Abweichungen vom zulässigen Betriebsfenster oder Havarien frühzeitig festzustellen, um Gegenmaßnahmen einzuleiten. Die Mess-wertaktualisierung/-abfrage sollte in der Regel wenige Minuten nicht überschreiten beziehungsweise die Systemträgheit widerspiegeln, um rechtzeitig Gegenmaßnahmen einzuleiten. Abweichungen vom zulässigen Betriebsfenster sollten je nach System nach 5 min bis 30 min eine Alarmierung auslösen.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-13' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12002-15-D1', 'kosten_summe_calc = sum_rows(kostenpositionen, kostenkennwert)', ARRAY['kostenpositionen']::text[], 'kosten_summe_calc', '€/m³ SW', '§8.2', 'Plan 3: Σ der Kostenkennwerte über die Verfahrensstufen — Text-Ableitung: §8.2 druckt spezifische Kosten je Stufe (L1450 "Für die einzelnen Stufen der Wasseraufbereitung sind nachfolgend spezifische Kosten … wiedergegeben"), keine Summenformel (m1200_2-F-1); Übernahme als kostenkennwert_aufbereitung STAGED (m1200_2-D-9).', 'imported_unverified', 'Für die einzelnen Stufen der Wasseraufbereitung sind nachfolgend spezifische Kosten in Euro je Kubikmeter ( $€ / \mathrm{m}^{3}$ ) Schmutzwasser (SW) wiedergegeben. Hierbei handelt es sich um grobe Richtwerte, die auf Basis von Kostenkurven und weiteren Erfahrungswerten zusammengestellt und mithilfe von Baupreisindizes auf das Jahr 2020 umgerechnet wurden. Die unteren Werte beziehen sich auf große Kläranlagen mit Ausbaugrößen von ca. 100.000 E , die oberen Werte stehen für kleinere Anlagen von ca. 10.000 E :'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12002-15' AND s.code = 'DWA-M-1200-2'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
COMMIT;
